function validate([s]) {
  if (s.length < 1 || s.length > 10000) return 's needs 1 to 10000 characters.';
  if (!/^[A-Za-z0-9 ]+$/.test(s)) return 's uses only letters, digits and spaces.';
  if (!/[A-Za-z0-9]/.test(s)) return 's needs at least one word.';
  return null;
}

