function reverseWords(s) {
  const words = [];
  let end = s.length - 1;

  while (end >= 0) {
    while (end >= 0 && s[end] === ' ') {
      end--;
    }
    if (end < 0) {
      break;
    }
    let start = end;
    while (start >= 0 && s[start] !== ' ') {
      start--;
    }
    words.push(s.slice(start + 1, end + 1));
    end = start;
  }
  return words.join(' ');
}

