function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const letters = large ? 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789' : (rand() < 0.5 ? 'aB1' : 'ab');
  const word = () => Array.from({ length: 1 + pick(large ? 8 : 3) }, () => letters[pick(letters.length)]).join('');
  const spaces = most => ' '.repeat(pick(most + 1));
  const limit = large ? 9970 : 1 + pick(6);
  let s = spaces(3) + word();
  for (let i = 1; i < limit; i++) {
    const next = ' ' + spaces(2) + word();
    if (large && s.length + next.length > 9970) break;
    s += next;
  }
  return [s + spaces(3)];
}
